/** Read a `CT_Authors`. See `transitional/sml.xsd:280`. */
export function readCT_Authors(cur: XmlCursor, ctx: ReadContext): CT_Authors {
  const start = requireStart(cur, 'CT_Authors');
  let $unknownAttrs: XmlAttr[] | undefined;

  for (const a of start.attrs) {
    ctx.unexpectedAttribute('CT_Authors', a, cur);
    ($unknownAttrs ??= []).push(a);
  }

  const author: ST_Xstring[] = [];
  let $unknown: PositionedRaw[] | undefined;
  let $slot = -1;
  let $index: number | undefined;

  const NS_sml = ctx.uris['sml'];
  cur.next();
  for (;;) {
    const ev = cur.current;
    if (ev === undefined) { ctx.unexpectedEof('CT_Authors', cur); break; }
    if (ev.type === 'endElement') { cur.next(); break; }
    if (ev.type === 'startElement') {
      if (ev.uri === NS_sml) {
        switch (ev.localName) {
          case 'author': {
            const $s = readScalar(cur, ctx);
            const $pv = parseST_Xstring($s);
            if ($pv === undefined) ctx.invalidElementValue('CT_Authors', 'author', 'ST_Xstring', $s, cur);
            author.push(($pv ?? $s) as ST_Xstring);
            $slot = 0;
            $index = author.length - 1;
            continue;
          }
        }
      }
      ctx.unexpectedElement('CT_Authors', ev.localName, ev.uri, cur);
      ($unknown ??= []).push({ afterSlot: $slot, afterIndex: $index, node: cur.skipToRaw() });
      continue;
    }
    if (ev.type === 'text' && !isIgnorableWhitespace(ev.value)) ctx.unexpectedText('CT_Authors', cur);
    cur.next();
  }

  return {
    author,
    $unknown,
    $unknownAttrs,
  };
}

